function git(cwd: string, args: string[], allowFailure = false): string { const result = Bun.spawnSync({ cmd: ["git", ...args], cwd, stdout: "pipe", stderr: "pipe" }); if (!allowFailure && result.exitCode !== 0) fail(`GIT_${args[0]}:${result.stderr.toString().trim()}`); return result.stdout.toString().trim(); }
