	for (let index = 0; index < rest.length; index++) { const key = rest[index]; if (key === "--lab-root") { if (lab || !rest[++index]) fail("LAB_ROOT_REQUIRED"); lab = rest[index]; } else if (key === "--concurrency") { const value = rest[++index]; if (!value || !/^[1-4]$/.test(value)) fail("CONCURRENCY_1_TO_4"); concurrency = Number(value); } else if (key === "--mock-executor") mock = true; else if (key === "--normal") normal = true; else fail(`UNKNOWN_FLAG:${key}`); }
