		const present = fields.filter(field => {
			const dependencies = value[field];
			return dependencies !== undefined && (!dependencies || typeof dependencies !== "object" || Array.isArray(dependencies) || Object.keys(dependencies).length > 0);
		});
		return present.length ? { required: true, reason: `ROOT_PACKAGE_DEPENDENCIES:${present.join(",")}`, manifest } : trackedRootLocks.length ? { required: true, reason: `ROOT_TRACKED_JAVASCRIPT_LOCKFILE:${trackedRootLocks.join(",")}`, manifest } : { required: false, reason: "ROOT_PACKAGE_DEPENDENCIES_ABSENT", manifest };
