const GATE_SCHEMA = { type: "object", additionalProperties: false, properties: { status: { type: "string", enum: ["PASS", "FAIL", "BLOCKED"] }, runId: { type: "string" }, generation: { type: "string" }, findings: { type: "array", items: { type: "object", additionalProperties: false, properties: { block: { type: "boolean" }, severity: { type: "string" }, summary: { type: "string" }, runId: { type: "string" }, generation: { type: "string" } }, required: ["block", "severity", "summary", "runId", "generation"] } }, evidence: { type: "array", items: { type: "string" } } }, required: ["status", "runId", "generation", "findings", "evidence"] };
type WorkerPlan = { schema: "omp-plan-automation-worker/v1"; mode: "lab" | "normal"; cwd: string; sessionFile?: string; sessionDir: string; commands: Array<{ input: Command; evidenceFile: string }> };
type WorkerResult = { ok: boolean; rootSessionFile?: string; rootSessionId?: string; results: Array<Record<string, any>>; failure?: { name: string; message: string } };
function workerPlan(attempt: Attempt, name: string, cwd: string, commands: Command[], session?: Context): string { const root = path.join(attempt.root, "workers", name); const file = path.join(root, "plan.json"); const sessionDir = session?.sessionDir ?? path.join(root, "session"); write(file, { schema: "omp-plan-automation-worker/v1", mode: attempt.mode.kind, cwd, sessionFile: session?.sessionFile, sessionDir, commands: commands.map((input, index) => ({ input, evidenceFile: path.join(root, `command-${index}.json`) })) }); return file; }
